const $=s=>document.querySelector(s);const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let socket,active,tabs=[],imageUrl,lastUrl='',resizeTimer,marks=[],dark=false;try{const p=JSON.parse(localStorage.getItem('dock-browser-web-v1')||'{}');marks=p.bookmarks||[];dark=p.dark||false}catch{}
function theme(){DockAppearance.apply();dark=DockAppearance.isDark()}function save(){try{localStorage.setItem('dock-browser-web-v1',JSON.stringify({bookmarks:marks,dark}))}catch{}}
function send(m){if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify(m))}function resizeRemote(){send({type:'resize',width:innerWidth,height:innerHeight-180})}
function enabled(on){for(const id of ['new-tab','back','forward','reload','address','go','bookmark','disconnect'])$('#'+id).disabled=!on}
function disconnected(message){enabled(false);$('#screen-wrap').hidden=true;$('#welcome').hidden=false;$('#message').textContent=message;$('#status').textContent='Disconnected';$('#connect').disabled=false;$('#connect').textContent='Reconnect';tabs=[];$('#tabs').innerHTML='';if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=null;$('#screen').removeAttribute('src')}
async function check(){try{const r=await fetch('/_browser/status',{cache:'no-store'});const data=await r.json();if(!r.ok||!data.configured)throw Error(data.message||'Browser server is not configured.');$('#message').textContent='Start a temporary Chromium session on your Mac. Searches and websites stay inside this view.';$('#status').textContent='Ready to connect';$('#connect').disabled=false;$('#connect').textContent='Connect';$('#connect').onclick=connect}catch(e){$('#message').textContent=e.message||'Could not check connection. Sign in again and retry.';$('#status').textContent='Setup required';$('#connect').disabled=false;$('#connect').textContent='Retry connection check';$('#connect').onclick=check}}
function render(){const t=tabs.find(t=>t.id===active);lastUrl=t?.url||'';if(document.activeElement!==$('#address'))$('#address').value=lastUrl==='about:blank'?'':lastUrl;$('#tabs').innerHTML=tabs.map(t=>`<div class="tab ${t.id===active?'active':''}"><button class="select" role="tab" aria-selected="${t.id===active}" data-select="${t.id}">${escape(t.title||'New tab')}</button><button class="close" aria-label="Close ${escape(t.title||'tab')}" data-close="${t.id}">×</button></div>`).join('');document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>send({type:'select',id:+b.dataset.select}));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>send({type:'close',id:+b.dataset.close}));$('#bookmark').textContent=marks.some(m=>m.url===lastUrl)?'★':'☆'}
function connect(){if(socket&&socket.readyState<2)return;$('#connect').disabled=true;$('#status').textContent='Connecting…';socket=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/_browser/socket`);socket.binaryType='blob';socket.onopen=()=>{resizeRemote();$('#welcome').hidden=true;$('#screen-wrap').hidden=false;enabled(true);$('#status').textContent='Connected · waiting for browser frame'};socket.onmessage=e=>{if(e.data instanceof Blob){const old=imageUrl;imageUrl=URL.createObjectURL(e.data);$('#screen').onload=()=>{if(old)URL.revokeObjectURL(old);send({type:'ack'});$('#status').textContent='Connected'};$('#screen').src=imageUrl;return}try{const m=JSON.parse(e.data);if(m.type==='state'){tabs=m.tabs;active=m.active;render()}if(m.type==='error')$('#status').textContent=m.message}catch{}};socket.onclose=e=>disconnected(e.reason||'The browser server disconnected. Start it on your Mac, then reconnect.');socket.onerror=()=>{$('#status').textContent='Could not connect to the browser server.'}}
window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(resizeRemote,120)});
$('#connect').onclick=connect;$('#disconnect').onclick=()=>socket?.close(1000,'Session closed');$('#navigation').onsubmit=e=>{e.preventDefault();send({type:'navigate',value:$('#address').value});$('#screen').focus()};for(const type of ['back','forward','reload'])$('#'+type).onclick=()=>send({type});$('#new-tab').onclick=()=>send({type:'new'});
$('#screen').onclick=e=>{const r=e.target.getBoundingClientRect();send({type:'click',x:(e.clientX-r.left)/r.width*e.target.naturalWidth,y:(e.clientY-r.top)/r.height*e.target.naturalHeight});e.target.focus()};$('#screen').addEventListener('wheel',e=>{e.preventDefault();send({type:'wheel',x:e.deltaX,y:e.deltaY})},{passive:false});$('#screen').onkeydown=e=>{if(e.key==='Tab'||e.key==='Enter'||e.key==='Backspace'||e.key.startsWith('Arrow')||['Escape','Delete','Home','End','PageUp','PageDown'].includes(e.key)){e.preventDefault();send({type:'key',value:e.key})}else if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='a'){e.preventDefault();send({type:'key',value:'ControlOrMeta+A'})}else if(e.key.length===1&&!e.metaKey&&!e.ctrlKey&&!e.altKey){e.preventDefault();send({type:'text',value:e.key})}};
function text(){if($('#typing').value){send({type:'text',value:$('#typing').value});$('#typing').value=''}}$('#send-text').onclick=text;$('#typing').onkeydown=e=>{if(e.key==='Enter'){text();send({type:'key',value:'Enter'})}};$('#enter').onclick=()=>{text();send({type:'key',value:'Enter'})};$('#erase').onclick=()=>send({type:'key',value:'Backspace'});$('#theme').onclick=()=>{DockAppearance.toggleTheme();theme();save()};
function showMarks(){$('#saved').innerHTML=marks.length?marks.map((m,i)=>`<div class="saved-row"><button class="open" data-mark="${i}">${escape(m.title)}</button><button data-remove="${i}" aria-label="Remove bookmark">×</button></div>`).join(''):'<p>No bookmarks yet.</p>';document.querySelectorAll('[data-mark]').forEach(b=>b.onclick=()=>{send({type:'navigate',value:marks[+b.dataset.mark].url});$('#bookmarks').hidden=true});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{marks.splice(+b.dataset.remove,1);save();showMarks()})}$('#bookmark').onclick=()=>{if(!lastUrl||lastUrl==='about:blank')return;marks=marks.some(m=>m.url===lastUrl)?marks.filter(m=>m.url!==lastUrl):[...marks,{url:lastUrl,title:tabs.find(t=>t.id===active)?.title||lastUrl}];save();render()};$('#marks').onclick=()=>{$('#bookmarks').hidden=!$('#bookmarks').hidden;showMarks()};$('#close-bookmarks').onclick=()=>$('#bookmarks').hidden=true;window.addEventListener('pagehide',()=>socket?.close());theme();check();
